let BUBBLE_ANIMATION = [
    "3",
    "1",
    "4",
    "2",
    "5",
];


cc.Class({
    extends: require("GoddessOfDeath_subGameBase"),

    properties: {
        _subGameNodeName: "subGameYellowFish",

        _lblStartPrize: null,
        _sprPickTips: null,

        _stonesList: null,
        _winList: null,

        _chooseCount: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._super();

        this._lblStartPrize = cc.find("nodePrizePool/theme163_game_c_2/lblStartPrize", this._node_main);
        this._sprPickTips = cc.find("nodeDetail/pickTips", this._node_main);

        this._stonesList = [];
        this._winList = [];
        for (let i=1; i<=5; i++) {
            this._stonesList[i] = cc.find("nodeDetail/stone/stone" + i, this._node_main);
            this._winList[i] = cc.find("nodeDetail/win/win" + i, this._node_main);
        }

        this.init();
    },

    init () {
        for (let i=1; i<=5; i++) {
            this._winList[i].active = false;

            let roralhNode = this._stonesList[i];
            roralhNode.getComponent(cc.Button).enabled = true;

            roralhNode.getChildByName("sprStone").active = true;

            let parrot = roralhNode.getChildByName("spineBreakStone");
            parrot.active = false;

            let bubble = roralhNode.getChildByName("spineGem");
            bubble.color = cc.Color.WHITE;
            bubble.active = false;
        }

        for (let node of cc.find("nodeDetail/mult", this._node_main).children) {
            node.active = false;
        }
    },

    restoreByData () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._subGameNode.active = true;
        this._chooseCount = gameInfo.useCnt;

        //i对应珊瑚 对应值是选中小鱼
        for (let i in gameInfo.gems) {
            let roralIdx = parseInt(i) + 1;
            let winIdx = gameInfo.gems[i];

            let roralhNode = this._stonesList[roralIdx];
            roralhNode.getComponent(cc.Button).enabled = winIdx == 0;

            roralhNode.getChildByName("sprStone").active = winIdx == 0;

            let gemNode = roralhNode.getChildByName("spineGem");
            if (winIdx != 0) {
                this.scheduleOnce(()=>{ //因为特效加载，导致特效错乱
                    this.playSpine(gemNode, null, "animation" + BUBBLE_ANIMATION[winIdx - 1], true);
                }, 1.0);
            }

            if (winIdx > 0) this._winList[winIdx].active = true;
        }
    },

    //进入游戏
    async enterGame () {
        this.init();

        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        this._chooseCount = gameInfo.useCnt || 0;
        this.setLabel(this._lblStartPrize, Global.FormatNumToComma(gameInfo.startPrize));

        return new Promise(async (success)=>{
            if (this._chooseCount == 0) { //刚进入
                await this.showStart();
            }
            else {
                //根据数据恢复显示
                this.restoreByData();
            }
            await this.showMain();
            await this.showResult();
            await this.exitGame();
            success();
        });
    },

    //退出游戏
    async exitGame () {
        return new Promise(async (success)=>{
            //全屏过渡
            await this.playFullScreen(2.0);
            this.setSubGameNodeVisible(false);
            success();
        });
    },

    //显示开始提示
    // async showStart () {
    //     return new Promise(async (success)=>{
    //         this._subGameNode.active = true;
    //         this._node_start.active = true;
    //         this._node_start.scale = 0;
    //         await this.playActions(this._node_start, [cc.scaleTo(0.35, 1.4), cc.scaleTo(0.15, 1.2)]);
    //         Global.btnClickEvent(this._node_start.getChildByName("btnStart"), ()=>{
    //             Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);
    //             this.playActions(this._node_start, [cc.scaleTo(0.15, 1.4), cc.scaleTo(0.35, 0)]);
    //             success();
    //         }, this);
    //     });
    // },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            //全屏过渡
            let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
            if (gameInfo.mult <= 0) await this.playFullScreen(1.5);
            //初始化
            this._node_start.active = false;
            this._node_main.active = true;
            await this.awaitTime(0.2);
            //等待玩家选择操作
            await this.awaitOrOperate();
            //等待操作提示
            this.setPlayPickTipsAction(false);
            //等待
            await this.awaitTime(1.0);
            success();
        });
    },

    setPlayPickTipsAction (isPlay) {
        if (isPlay) {
            this.playSpine(this._sprPickTips, null, "animation", true);
        }
        else {
            this.playSpine(this._sprPickTips, null, "animation2", true);
        }

        //珊瑚是否可点
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        for (let i in gameInfo.gems) {
            let roralIdx = parseInt(i) + 1;
            let winIdx = gameInfo.gems[i];

            let roralhNode = this._stonesList[roralIdx];
            roralhNode.getComponent(cc.Button).enabled = isPlay && winIdx == 0;
        }
    },

    async awaitOrOperate () {
        return new Promise(async (success, failed)=>{
            //提示，以及金币规律跳动
            this.setPlayPickTipsAction(true);

            for (let i=1; i<=5; i++) {
                let item = this._stonesList[i];
                item.off("click");
                Global.btnClickEvent(item, async ()=>{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);
                    //停止操作提示动作
                    this.setPlayPickTipsAction(false);
                    let resp = await cc.vv.gameData.reqSubGame(Global.GOLD_TREASURE_MAP_RTYPE.OPERATE_SUBGAME, i);
                    if (resp.code === 200) {
                        let gameInfo = resp.data.mapInfo.gameInfo;
                        let winIdx = gameInfo.gems[i - 1];

                        //设置成不可操作
                        item.getComponent(cc.Button).enabled = false;

                        //播放拨开海草动作
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.land1_break);
                        let stone = item.getChildByName("sprStone");
                        stone.active = false;

                        let breakStone = item.getChildByName("spineBreakStone");
                        this.playSpine(breakStone, ()=>{
                            breakStone.active = false;
                        }, "animation", false);

                        let gemNode = item.getChildByName("spineGem");
                        this.playSpine(gemNode, null, "animation" + BUBBLE_ANIMATION[winIdx - 1], true);
                        await this.awaitTime(0.5);

                        //显示中奖
                        this.playWin(winIdx);
                        await this.awaitTime(0.5);

                        if (gameInfo.winCoin > 0) {
                            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.land1_full);

                            cc.find("nodeDetail/mult/spineMult_" + gameInfo.mult, this._node_main).active = true;

                            await this.awaitTime(0.8);
                            for (let j=1; j<=5; j++) {
                                let titem = this._stonesList[j];
                                let tgemNode = titem.getChildByName("spineGem");
                                if (!tgemNode.active) {
                                    titem.getChildByName("sprStone").active = false;
                                    titem.getChildByName("spineBreakStone").active = false;

                                    tgemNode.color = cc.Color.GRAY;
                                    this.playSpine(tgemNode, null, "animation" + BUBBLE_ANIMATION[gameInfo.gems[j - 1] - 1], true);
                                }
                            }
                            await this.awaitTime(1.5);
                            success();
                        }
                        else {
                            //提示，以及金币规律跳动
                            this.setPlayPickTipsAction(true);
                        }
                    }
                    else {
                        console.log("返回数据错误!");
                        failed();
                    }
                });
            }
        });
    },

    playWin (winIdx) {
        this._winList[winIdx].active = true;
        for (let winnode of this._winList[winIdx].children) {
            this.playSpine(winnode.getChildByName("spine_lizi"), null, "animation", false);
        }
    },

    //显示游戏结果
    async showResult () {
        return new Promise(async (success)=>{
            this._node_win.active = true;

            let ui = this._node_win.getChildByName("ui");
            ui.scale = 0;

            let baseCoin = Global.FormatCommaNumToNum(this._lblStartPrize.getComponent(cc.Label).string);
            let mult = cc.vv.gameData.mapInfo.gameInfo.mult;

            //屏蔽collect按钮
            let btnCollect = ui.getChildByName("btnCollect");
            btnCollect.getComponent(cc.Button).enabled = false;

            //显示公式
            this.setLabel(ui.getChildByName("lblWinCoinShow"), mult + " X " + this.convertNumToShortStr(baseCoin) + " = " + this.convertNumToShortStr(mult*baseCoin));
            //动态刷新赢取金币数
            this.rollToNumOfLabel(ui.getChildByName("lblWinCoin"), mult*baseCoin);
            cc.vv.gameData.setSubGameWinCoin(mult*baseCoin);

            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.popup_map2);

            //播放动画
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            //开启collect按钮
            btnCollect.getComponent(cc.Button).enabled = true;
            let self = this;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);

                btnCollect.getComponent(cc.Button).enabled = false;

                ui.getChildByName("lblWinCoin").stopAllActions();
                self.setLabel(ui.getChildByName("lblWinCoin"), self.convertNumToShortStr(mult*baseCoin));
                self.playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);
                success();
            };
            cc.vv.gameData.checkAutoPlay(btnCollect, clickFunc);
            Global.btnClickEvent(btnCollect, ()=>{
                btnCollect.stopAllActions();
                clickFunc();
            }, this);
        });
    },
});
