let MULT_ARR = [16,36,60,180,600];

cc.Class({
    extends: require("GoddessOfDeath_subGameBase"),

    properties: {
        _subGameNodeName: "subGameRenyu",

        _lblStartPrize: null,
        _lblPickMult: null,
        _lblPickLeft: null,
        _goldCoinItems: null,
        _sprPickTips: null,

        _pickLeftNum: 3,
        _pickMultNum: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._super();

        this._lblStartPrize = cc.find("nodePrizePool/theme163_game_c_2/lblStartPrize", this._node_main);

        this._lblPickMult = cc.find("nodePrizePool/theme163_game_c_3/lblPickMult", this._node_main);
        this._lblPickLeft = cc.find("theme163_game5_5/lblPickLeft", this._node_main);
        this._sprPickTips = cc.find("theme163_game5_1", this._node_main);

        this._goldCoinItems = [];
        let listNode = cc.find("nodeRenyuGoldcoinList", this._node_main);
        let template = listNode.getChildByName("ItemNode");
        template.active = false;
        for (let i=1; i<=12; i++) {
            let itemNode = cc.instantiate(template);
            itemNode.parent = listNode;
            itemNode.name = "ItemNode" + i;
            itemNode.active = true;
            this._goldCoinItems.push(itemNode);
        }

        //初始化各种显示状态
        this.init();

        //测试
        // this.enterGame();
    },

    init () {
        this.setLabel(this._lblStartPrize, "");
        this.setLabel(this._lblPickMult, this._pickMultNum? this._pickMultNum + "X":"");
        for (let item of this._goldCoinItems) {
            item.getChildByName("spineRenyuGoldcoin").active = true;
            item.getChildByName("sprPickMult").active = false;
            item.getChildByName("sprAdd1Pick").active = false;
            this.setGoldCoinGray(item, false);
            this.playSpine(item.getChildByName("spineRenyuGoldcoin"), null, "animation3", false);
        }
    },

    restoreByData () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._subGameNode.active = true;
        this.setLabel(this._lblPickMult, gameInfo.mult + "X");

        for (let i in gameInfo.choiceIds) {
            let id = gameInfo.choiceIds[i];
            let result = gameInfo.choiceItems[i];
            let item = this._goldCoinItems[id - 1];

            //显示倍数
            let sprMult = item.getChildByName("sprPickMult");
            sprMult.active = true;
            sprMult.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game_gun").getSpriteFrame("theme141_game5_cnt" + result.mult);

            //如果有加选择次数
            let add1Pick = result.cnt;
            if (add1Pick) {
                sprMult.scale = 0.75;

                let sprAddPick = item.getChildByName("sprAdd1Pick");
                sprAddPick.active = true;
            }
            //火花状态
            this.playSpine(item.getChildByName("spineRenyuGoldcoin"), null, "animation4", false);
        }
    },

    //进入游戏
    async enterGame () {
        this.init();

        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._pickLeftNum = gameInfo.restCnt;
        this._pickMultNum = gameInfo.mult;
        this.setLabel(this._lblStartPrize, Global.FormatNumToComma(gameInfo.startPrize));

        return new Promise(async (success)=>{
            if (this._pickMultNum <= 0) {
                await this.showStart();
            }
            await this.showMain();
            await this.showResult();
            await this.exitGame();
            success();
        });
    },

    //退出游戏
    async exitGame () {
        return new Promise(async (success)=>{
            //全屏过渡
            await this.playFullScreen(2.0);
            this.setSubGameNodeVisible(false);
            success();
        });
    },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            //全屏过渡
            if (this._pickMultNum <= 0) await this.playFullScreen(1.5);
            //初始化
            this._node_start.active = false;
            this._node_main.active = true;
            this.setLabel(this._lblPickLeft, this._pickLeftNum);

            //断线重连
            //根据数据恢复显示
            if (this._pickMultNum > 0) this.restoreByData();
            await this.awaitTime(1.0);
            //等待玩家选择操作
            await this.awaitOrOperate();
            //变灰
            this.setPlayPickTipsAction(false);
            for (let item of this._goldCoinItems) {
                this.setGoldCoinGray(item, !item.getChildByName("sprPickMult").active);
            }
            await this.awaitTime(2.0);

            success();
        });
    },

    setPlayPickTipsAction (isPlay) {
        if (isPlay) {
            this._sprPickTips.scale = 1.0;
            this._sprPickTips.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.5,0.9), cc.scaleTo(0.2,1.0), cc.delayTime(2.0))));
            for (let item of this._goldCoinItems) {
                if (!item.getChildByName("sprPickMult").active) {
                    setTimeout(()=>{
                        if (!item.getChildByName("sprPickMult").active) {
                            this.playSpine(item.getChildByName("spineRenyuGoldcoin"), null, "animation1", true);
                        }
                    }, Global.random0To1() >= 0.5?500:1500);
                    item.getComponent(cc.Button).enabled = true;
                }
            }
        }
        else {
            this._sprPickTips.stopAllActions();
            this._sprPickTips.scale = 1.0;

            for (let item of this._goldCoinItems) {
                if (!item.getChildByName("sprPickMult").active) {
                    this.playSpine(item.getChildByName("spineRenyuGoldcoin"), null, "animation3", false);
                }
                item.getComponent(cc.Button).enabled = false;
            }
        }
    },

    async awaitOrOperate () {
        return new Promise(async (success, failed)=>{
            //提示，以及金币规律跳动
            this.setPlayPickTipsAction(true);

            for (let item of this._goldCoinItems) {
                item.off("click");

                Global.btnClickEvent(item, async ()=>{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);

                    //停止操作提示动作
                    this.setPlayPickTipsAction(false);

                    let resp = await cc.vv.gameData.reqSubGame(Global.GOLD_TREASURE_MAP_RTYPE.OPERATE_SUBGAME, parseInt(item.name.substring(8,item.name.length)));
                    if (resp.code === 200) {
                        let gameData = resp.data.mapInfo.gameInfo;
                        let resultList = gameData.choiceItems;
                        let curChoiceData = resultList[resultList.length - 1];
                        this._pickLeftNum --;

                        //碎裂
                        this.playSpine(item.getChildByName("spineRenyuGoldcoin"), ()=>{
                            this.playSpine(item.getChildByName("spineRenyuGoldcoin"), null, "animation4", false);
                        }, "animation2", false);
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.land5_click);

                        //剩余次数
                        this.setLabel(this._lblPickLeft, this._pickLeftNum);
                        //显示倍数
                        item.getChildByName("sprPickMult").active = true;
                        item.getChildByName("sprPickMult").getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game_gun").getSpriteFrame("theme141_game5_cnt" + curChoiceData.mult);

                        //如果有加选择次数
                        let add1Pick = curChoiceData.cnt;
                        this._pickLeftNum = gameData.restCnt;
                        if (add1Pick) {
                            item.getChildByName("sprAdd1Pick").active = true;
                            this.playActions(item.getChildByName("sprAdd1Pick"), [cc.scaleTo(0.5, 1.0)]);
                        }

                        await this.playActions(item.getChildByName("sprPickMult"), [cc.scaleTo(0.5, add1Pick?0.75:1.0)]);

                        if (add1Pick){ //开出选择次数飞特效
                            this.playAddPickFlyEff(item);
                        }
                        //开出倍数飞的特效
                        // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.touzi_fly);
                        await this.playMultFlyEff(item, curChoiceData.mult);
                        // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.touzi_extra);

                        //剩余次数
                        this.setLabel(this._lblPickLeft, this._pickLeftNum);

                        if (this._pickLeftNum > 0) {
                            //提示，以及金币规律跳动
                            this.setPlayPickTipsAction(true);
                        }
                        else {
                            success();
                        }
                    }
                    else {
                        console.log("返回数据错误!");
                        failed();
                    }

                }, this);
            }
        });
    },

    async playMultFlyEff (itemNode, mult) {
        return new Promise(async (success)=>{
            // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.fly_mul);

            let beginPos = this._node_main.convertToNodeSpaceAR(itemNode.parent.convertToWorldSpaceAR(itemNode.position));

            let targetNode = cc.find("nodePrizePool/theme163_game_c_3", this._node_main);
            let targetPos = this._node_main.convertToNodeSpaceAR(targetNode.parent.convertToWorldSpaceAR(targetNode.position));

            let nodeFly = cc.find("nodeFlyMultNum", this._node_main);
            nodeFly.position = beginPos;
            nodeFly.scale = 1.0;

            nodeFly.getComponent(cc.ParticleSystem).resetSystem();

            await this.playActions(nodeFly, [cc.moveTo(0.3, targetPos), cc.scaleTo(0.1, 0)]);

            let spineNodeMult = cc.find("nodePrizePool/spineNodeMult", this._node_main);
            this.playSpine(spineNodeMult);
            await this.awaitTime(0.2);

            this._pickMultNum += mult;
            this.setLabel(this._lblPickMult, this._pickMultNum? this._pickMultNum + "X":"");

            success();
        });
    },

    playAddPickFlyEff (itemNode) {
        let beginPos = this._node_main.convertToNodeSpaceAR(itemNode.parent.convertToWorldSpaceAR(itemNode.position));
        let targetPos = this._node_main.convertToNodeSpaceAR(this._lblPickLeft.parent.convertToWorldSpaceAR(this._lblPickLeft.position));

        let nodeFly = cc.find("nodeFlyPickNum", this._node_main);
        nodeFly.position = beginPos;
        nodeFly.scale = 1.0;

        let p = nodeFly.getComponent(cc.ParticleSystem);
        p.resetSystem();

        this.playActions(nodeFly, [cc.moveTo(0.5, targetPos), cc.scaleTo(0.1, 0)]);
    },

    setGoldCoinGray (itemNode, isGray) {
        if (isGray) {
            this.playSpine(itemNode.getChildByName("spineRenyuGoldcoin"), null, "animation3", false);

            let isAddPick = Global.random0To1() > 0.7;
            itemNode.getChildByName("sprPickMult").active = true;
            itemNode.getChildByName("sprPickMult").scale = isAddPick?0.75:1;
            itemNode.getChildByName("sprPickMult").getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game_gun").getSpriteFrame("theme141_game5_cnt" + MULT_ARR[Math.floor(Global.random0To1()*100)%MULT_ARR.length]);

            itemNode.getChildByName("sprAdd1Pick").active = isAddPick;
        }

        let color = isGray?cc.Color.GRAY:cc.Color.WHITE;
        for (let subNode of itemNode.children) {
            subNode.color = color;
        }
    },

    //显示游戏结果
    async showResult () {
        return new Promise(async (success)=>{
            this._node_win.active = true;

            let ui = this._node_win.getChildByName("ui");
            ui.scale = 0;

            let baseCoin = Global.FormatCommaNumToNum(this._lblStartPrize.getComponent(cc.Label).string);

            //屏蔽collect按钮
            let btnCollect = ui.getChildByName("btnCollect");
            btnCollect.getComponent(cc.Button).enabled = false;

            //显示公式
            this.setLabel(ui.getChildByName("lblWinCoinShow"), this._pickMultNum + " X " + this.convertNumToShortStr(baseCoin) + " = " + this.convertNumToShortStr(this._pickMultNum*baseCoin));
            //动态刷新赢取金币数
            this.rollToNumOfLabel(ui.getChildByName("lblWinCoin"), this._pickMultNum*baseCoin);
            cc.vv.gameData.setSubGameWinCoin(this._pickMultNum*baseCoin);

            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.popup_map2);
            //播放动画
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            //开启collect按钮
            btnCollect.getComponent(cc.Button).enabled = true;
            let self = this;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);

                btnCollect.getComponent(cc.Button).enabled = false;
                ui.getChildByName("lblWinCoin").stopAllActions();
                self.setLabel(ui.getChildByName("lblWinCoin"), self.convertNumToShortStr(self._pickMultNum*baseCoin));
                self.playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);
                success();
            };
            cc.vv.gameData.checkAutoPlay(btnCollect, clickFunc);
            Global.btnClickEvent(btnCollect, ()=>{
                btnCollect.stopAllActions();
                clickFunc();
            }, this);
        });
    },
});
