cc.Class({
    extends: cc.Component,

    properties: {
        _soundPath: "games/GoddessOfDeath/",
        _subGameNode: null,
        _node_main: null,
        _spineNodeLoading: null,

        _targetIdx:7, //0-65，1-90，2-45，... ，7-75
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._subGameNode = cc.find("/subGameCollectWheel", this.node);
        this._node_main = cc.find("node_main", this._subGameNode);
        this._spineNodeLoading = cc.find("spineNodeLoading", this._subGameNode);

        //初始化各种显示状态
        this.init();

        //测试
        // this.enterGame();
    },

    init () {
        this._spineNodeLoading.active = false;
        this._subGameNode.active = false;
        this._node_main.active = false;

        cc.find("wheel/spineEff1", this._node_main).active = false;
        cc.find("wheel/spineEff2", this._node_main).active = false;
        cc.find("wheel/spineEffWin", this._node_main).active = false;

        let bottom = cc.find("bottom", this._node_main);
        bottom.y = -700;

        let wheel = cc.find("wheel", this._node_main);
        wheel.scale = 0;
    },

    //进入游戏
    async enterGame () {
        this._targetIdx = 0;

        this.init();
        await this.showMain();
        await this.showResult();
        await this.exitGame();
    },

    //退出游戏
    async exitGame () {
        await this.awaitTime(1.0);

        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.popup_out);
        // await this.playActions(this._node_main, [cc.scaleTo(0.2, 1.3), cc.scaleTo(0.5, 0)]);
        await this.hide();
        this._subGameNode.active = false;
    },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            this._subGameNode.active = true;
            await this.awaitTime(0.5);
            // //初始化
            this._node_main.active = true;
            // this._node_main.scale = 0;
            cc.find("wheel/spineEff1", this._node_main).active = true;
            cc.find("wheel/spineEff2", this._node_main).active = true;
            let btn_spin = cc.find("wheel/btn_spin", this._node_main);
            btn_spin.getComponent(cc.Button).enabled = false;

            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.popup_out);
            // await this.playActions(this._node_main, [cc.scaleTo(0.5, 1.3), cc.scaleTo(0.2, 1.2)]);
            await this.show();
            //等待玩家选择操作
            await this.awaitOrOperate();

            //下一步
            success();
        });
    },

    async show () {
        let bottom = cc.find("bottom", this._node_main);
        bottom.y = -700;
        cc.tween(bottom).to(0.3, {y:0}).start();

        let wheel = cc.find("wheel", this._node_main);
        wheel.scale = 0;
        cc.tween(wheel).to(0.3, {scale:1.4}).to(0.3, {scale:1.0}).start();

        await this.awaitTime(0.6);
    },

    async hide () {
        let bottom = cc.find("bottom", this._node_main);
        bottom.y = 0;
        cc.tween(bottom).delay(0.2).to(0.3, {y:-700}).start();

        let wheel = cc.find("wheel", this._node_main);
        wheel.scale = 1.0;
        cc.tween(wheel).to(0.3, {scale:1.4}).to(0.3, {scale:0}).start();

        await this.awaitTime(0.6);
    },

    async awaitOrOperate () {
        return new Promise(async (success)=>{
            let btn_spin = cc.find("wheel/btn_spin", this._node_main);
            btn_spin.getComponent(cc.Button).enabled = true;
            btn_spin.getComponent(cc.Button).interactable = true;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.map_wheel_click);

                btn_spin.getComponent(cc.Button).interactable = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn_spin, clickFunc);
            Global.btnClickEvent(btn_spin, ()=>{
                btn_spin.stopAllActions();
                clickFunc();
            });
        });
    },

    //显示游戏结果(开始旋转)
    async showResult () {
        return new Promise(async (success)=>{
            cc.find("wheel/spineEff1", this._node_main).active = false;
            cc.find("wheel/spineEff2", this._node_main).active = false;

            let resp = await cc.vv.gameData.reqSubGame(Global.GOLD_TREASURE_MAP_RTYPE.COLLECT_WHEEL);
            if (resp.code === 200) {
                Global.GoddessOfDeathCollectProgress.setCollectNum(resp.data.needCoins);

                this._targetIdx = resp.data.idx - 1;

                let rorationWheel = cc.find("wheel/rorationWheel", this._node_main);
                // rorationWheel.angle = 0;

                let targetAngle = this._targetIdx*45;

                let diffAngle = targetAngle - rorationWheel.angle;

                let mRound = 10; //转动圈数

                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.map_wheel_spin);
                await this.playActions(rorationWheel, [
                    cc.rotateTo(0.5*mRound, rorationWheel.angle + 360*mRound + diffAngle).easing(cc.easeSineInOut()),
                ]);

                Global.SlotsSoundMgr.stopEffectByName(Global.SlotsSoundMgr.map_wheel_spin);
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.map_wheel_show);

                cc.find("wheel/spineEffWin", this._node_main).active = true;
                success();
            }
            else {
                AppLog.err("请求数据错误");
            }
        });
    },

    playSpine (node, endCall, animationName="animation", isLoop=false) {
        if (node) {
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
            if (!isLoop) {
                node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    if (endCall) endCall();
                });
            }
        }
        else {
            if (endCall) endCall();
        }
    },

    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
