/**
 * 弹窗管理
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _showNode:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    /**
     * 显示10倍FreeGames
     */
    async showFreeCount (freeCount) {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_dialog_start_show);

            //显示10倍FreeGames
            let free_game_start = cc.find("free_game_start", this.node);
            free_game_start.active = true;

            let ui = free_game_start.getChildByName("ui");
            ui.scale = 0;
            ui.runAction(cc.sequence(cc.scaleTo(0.5, 1.2), cc.scaleTo(0.2, 1.0)));

            cc.find("lblFreeCount", ui).getComponent(cc.Label).string = (freeCount || 10).toString();

            let btnStart = ui.getChildByName("btnStart");
            btnStart.getComponent(cc.Button).enabled = false;
            await this.delayTime(1.0);
            btnStart.getComponent(cc.Button).enabled = true;

            btnStart.off("click");
            let self = this;
            let clickFunc = async ()=>{
                btnStart.getComponent(cc.Button).enabled = false;

                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.popup_out);
                ui.runAction(cc.sequence(cc.scaleTo(0.2, 1.2), cc.scaleTo(0.5, 0)));

                self.showTransitionFreePage();
                await self.delayTime(1);
                free_game_start.active = false;

                Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.free_bgm);

                success();
            };
            cc.vv.gameData.checkAutoPlay(btnStart, clickFunc);
            Global.btnClickEvent(btnStart, async ()=>{
                btnStart.stopAllActions();
                clickFunc();
            },this);
        });
    },


    async showFreeAgain (freeCount) {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_dialog_start_show);

            //显示10倍FreeGames
            let free_game_again = cc.find("free_game_again", this.node);
            free_game_again.active = true;

            let ui = free_game_again.getChildByName("ui");
            ui.scale = 0;
            ui.runAction(cc.sequence(cc.scaleTo(0.5, 1.2), cc.scaleTo(0.2, 1.0)));

            cc.find("lblFreeCount", ui).getComponent(cc.Label).string = (freeCount || 10).toString();

            // let btnStart = ui.getChildByName("btnStart");
            // btnStart.getComponent(cc.Button).enabled = false;
            await this.delayTime(2);
            // btnStart.getComponent(cc.Button).enabled = true;
            //
            // btnStart.off("click");
            // Global.btnClickEvent(btnStart, async ()=>{
            //     btnStart.getComponent(cc.Button).enabled = false;

                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.popup_out);
                ui.runAction(cc.sequence(cc.scaleTo(0.2, 1.2), cc.scaleTo(0.5, 0)));

                // this.showTransitionFreePage();
                await this.delayTime(1);
                free_game_again.active = false;

                // Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.free_bgm);

                success();
            // },this);
        });
    },

    /**
     * 显示过渡页
     */
    async showTransitionFreePage () {
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_free);

        let freeGameLoading = cc.find("freeGameLoading", this.node);
        this.playSpine(freeGameLoading, ()=>{
            freeGameLoading.active = false;
        });  
    },

    /**
     * 显示过渡页
     */
    async showLoadingPage () {
        return new Promise((success)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_bonus);

            let subGameLoading = cc.find("subGameLoading", this.node);
            subGameLoading.active = true;
            let spineNode = cc.find("spineNode", subGameLoading);
            this.playSpine(spineNode, ()=>{
                subGameLoading.active = false;
                success();
            });
        });
    },

    /**
     * 显示结算
     * @returns {Promise<void>}
     */
    async showSttlDialog () {
        return new Promise(async (success)=>{
            let free_game_win = cc.find("free_game_win", this.node);
            free_game_win.active = true;

            let ui = free_game_win.getChildByName("ui");
            ui.scale = 0;

            ui.getChildByName("lblWinCoin").getComponent(cc.Label).string = "";

            let btnCollect = ui.getChildByName("btnCollect");
            btnCollect.getComponent(cc.Button).enabled = false;

            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_dialog_collect_show);
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            Global.doRoallNumEff(ui.getChildByName("lblWinCoin"), 0, cc.vv.gameData._gameInfo.freeWinCoin || 0,3,null,null,0,true);

            // await this.delayTime(2.0);
            btnCollect.getComponent(cc.Button).enabled = true;

            btnCollect.off("click");
            let self = this;
            let clickFunc =  async ()=>{
                btnCollect.getComponent(cc.Button).enabled = false;

                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.popup_out);

                ui.getChildByName("lblWinCoin").getComponent(cc.Label).string = Global.FormatNumToComma(cc.vv.gameData._gameInfo.freeWinCoin || 0);
                await self.delayTime(0.1);

                free_game_win.active = false;
                self.showTransitionFreePage();
                await self.delayTime(1);

                Global.SlotsSoundMgr.stopBgm();

                success();
            };
            cc.vv.gameData.checkAutoPlay(btnCollect, clickFunc);
            Global.btnClickEvent(btnCollect, async ()=>{
                btnCollect.stopAllActions();
                clickFunc()
            },this);
        });
    },

    /**
     * 显示收集金币中Jackpot
     * @returns {Promise<void>}
     */
    async showCollectCoinJackpotWin (winNum, jackpotId) {
        return new Promise(async (success)=>{
            let winNode = cc.find("collect_coin_jackpot_win", this.node);
            winNode.active = true;

            let ui = winNode.getChildByName("ui");
            ui.scale = 0;

            let logo = cc.find("jackpot_logo", ui);
            logo.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("dialog_jackpot").getSpriteFrame("theme141_p_j_type" + (5 - jackpotId));

            ui.getChildByName("lblWinCoin").getComponent(cc.Label).string = "";

            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.win_jp_show);
            await this.playActions(ui, [cc.scaleTo(0.2, 1.3), cc.scaleTo(0.08, 1.0)]);


            Global.doRoallNumEff(ui.getChildByName("lblWinCoin"), 0, winNum,3,null,null,0,true);

            await this.delayTime(5.0);

            ui.scale = 1.0;
            Global.SlotsSoundMgr.playEffect("popup_out");
            await this.playActions(ui, [cc.scaleTo(0.08, 1.3), cc.scaleTo(0.2, 0)]);
            winNode.active = false;

            success();
        });
    },

    delayTime(time) {
        return new Promise((res, rej) => {
            this.scheduleOnce(()=>{res()}, time);
        });
    },

    playSpine (node, endCall, animationName="animation", isLoop=false) {
        if (node) {
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
            if (!isLoop) {
                node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    if (endCall) endCall();
                });
            }
        }
        else {
            if (endCall) endCall();
        }
    },

    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },
});
