cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:
    onLoad () {
        this._super();

        let safe_node = cc.find('safe_node',this.node)

        //slotsMgr
        let node_slotsMgr = cc.find('SlotsMgr',safe_node);
        let script_slotsMgr = node_slotsMgr.addComponent("GoddessOfDeath_SlotsMgr");
        script_slotsMgr.init(cc.find('slots',safe_node));
    },

    start () {
        this._super();
    },

});
