/**海盗船-符号表
 * 
*/
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    //重写
    StartMove:function(){
        this._super()

        //清除指定
        if (this._showCoinNode) {
            this._showCoinNode.active = false;
            this._showCoinNode = null;
        }
    },

    //停止旋转时刻
    //可做一些停止动作，比如scatter的缩放显示
    StopMoveEnd:function(){
        this._super();

        //考虑收集金币播放特效
        this.playCoinStopEff();
    },

    playCoinStopEff: function () {
        let cfg = cc.vv.gameData.getGameCfg()

        if (this._data && this._data.t == "coin") {
            let coinData = cfg.symbol[100]; //金币数据
            if(coinData && coinData.win_node) {
                this._showCoinNode = cc.find(coinData.win_node, this.node)
                this._showCoinNode.active = true

                let stop_anim = coinData.stop_ani;
                if(stop_anim){
                    let nodeSp = this._showCoinNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0, stop_anim, false);
                        nodeSp.setCompleteListener(()=>{
                            nodeSp.setCompleteListener(null);
                        });
                    }

                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.coin_show);
                }
            }
        }
    },

    isNeedCollectCoin: function () {
        return (this._data && this._data.t == "coin")
    },

    PlayCollectCoinAction: function (targetNode, callback) {
        console.log(this._id, "PlayCollectCoinAction0");

        if (this._showCoinNode && this._showCoinNode.active) {
            let cfg = cc.vv.gameData.getGameCfg()

            let parentNode = cc.find('Canvas/safe_node')

            //同时实例化scatter对象 移动用
            let flyNode = cc.instantiate(this._showCoinNode);
            flyNode.active = false;
            flyNode.parent = parentNode
            let beiginPos = parentNode.convertToNodeSpaceAR(this.node.convertToWorldSpaceAR(cc.v2(0,0)))
            flyNode.position = beiginPos

            //开始移动
            this.node.runAction(cc.sequence(cc.delayTime(0.5),cc.callFunc(()=>{
                if (this._showCoinNode) {
                    this._showCoinNode.active = false;
                    this._showCoinNode = null;
                }

                flyNode.active = true;

                let coinData = cfg.symbol[100]; //金币数据
                let fly_anim = coinData.fly_anim;
                if(fly_anim){
                    let nodeSp = flyNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0, fly_anim, false);
                    }
                }

                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.coin_fly);
                let tarPos = parentNode.convertToNodeSpaceAR(targetNode.convertToWorldSpaceAR(cc.v2(-37,22)))
                cc.tween(flyNode)
                // .spawn(cc.bezierTo(0.5,cc.v2(beiginPos.x,beiginPos.y),cc.v2(tarPos.x,beiginPos.y),cc.v2(tarPos.x,tarPos.y)), cc.scaleTo(0.5, 0.1))
                    .bezierTo(0.5,cc.v2(beiginPos.x,beiginPos.y),cc.v2(tarPos.x,beiginPos.y),cc.v2(tarPos.x,tarPos.y),{scale:0.3})
                    .call(() => {
                        callback();
                        flyNode.destroy()
                    }).start()
                })
            ));

        }
    },

    //显示中奖效果
    playWinAnimation:function(){
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true

            let win_anim = cfg.symbol[id].win_ani;
            if (cc.vv.gameData.isFreeGamesTime() || cc.vv.gameData.isMultipleSlots()) {
                if (cfg.symbol[id].win_ani_free) win_anim = cfg.symbol[id].win_ani_free;
            }

            if(win_anim && win_anim.name != ""){
                aniNode.zIndex = win_anim.zIndex - this._symbolIdx + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,win_anim.name,true)
                }
            }
        }
        else{
            //如果没有中奖动画，先显示出来
            //TODO：后续补充一个没有spin动画的显示效果
            this._showNode.active = true
            this.playWinTweenAction()
        }
    },

    //播放win效果但又没有spin动画。自己写一个tween的action
    //先填写个默认的。
    playWinTweenAction(){
        this._showNode.cleanup()
        //记录原始缩放
        let nOpacity = this._showNode.opacity;
        this._showNodeOrgOpacity = nOpacity

        cc.tween(this._showNode)
            .repeatForever(cc.tween()
                .to(0.35,{opacity:0})
                .to(0.3,{opacity:nOpacity})
                .delay(0.6)
            )
            .start()
    },
});
