// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {
        _slotsTemplate: null,
        _slotsCacheList: null,
        
        _slotsActiveList: null,
        _curSlotId: 0,

        _collect_jackpot: 0,
        _spine_role: 0,

        _gameInfo: null,
    },

    // LIFE-CYCLE CALLBACKS:
    onLoad () {
        this._slotsCacheList = [];

        this._slotsActiveList = [];

        this._collect_jackpot = cc.find("collect_jackpot", this.node.parent);
        //- this._spine_role = cc.find("spine_role", this.node.parent);

        this._bonusBottom = cc.find("bonusBottom", this.node);
        this._bonusBottom.zIndex = 200;
        this._bonusBottom.active = false;

        Global.SlotsMgr = this;

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvNetMsgBonusGame, false, this);
    },

    onDestroy () {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvNetMsgBonusGame, false, this);
    },

    init (slotsTemplate) {
        this._slotsTemplate = slotsTemplate;
        this._slotsTemplate.getComponent(cc.Widget).updateAlignment();
        // this._slotsTemplate.active = false;
    },

    start () {
        this._slotsTemplate.active = false;
        //增加一个Slots
        this.add1Slot();

        //设置为当前活跃Slot
        this.setCurActiveSlot(0); //默认是0
        //设置jackpot位置
        this.scheduleOnce(()=>{
            this._collect_jackpot.position = this.getCollectJackpotPos();
        }, 0.03);

        this.showBottomInfo(false);

        //断线重连恢复
        this.restoreByServerData();
    },

    onRcvNetMsgBonusGame (msg) {
        if (msg.code === 200) {
            // msg = {"data":{"zjLuXian":[{"mult":1,"coin":9000,"card":6,"xlid":4,"indexs":[1,7,13]},{"mult":1,"coin":15000,"card":4,"xlid":6,"indexs":[6,2,3]},{"mult":1,"coin":15000,"card":4,"xlid":16,"indexs":[6,7,3]},{"mult":1,"coin":9000,"card":6,"xlid":18,"indexs":[1,2,13]},{"mult":1,"coin":9000,"card":6,"xlid":20,"indexs":[1,12,13]}],"code":200,"betcoin":20000,"wincoin":133000,"scatterZJLuXian":{"indexs":[],"mult":0,"coin":0},"freeCnt":7,"bonusGame":{"stepCnt":2,"winCoin":0,"scatterResult":[],"scatterCnt":1,"nextSlotIdx":3,"currSlotIdx":3,"traceResult":[],"allSlotCards":[[1,5,6,5,5,1,5,6,6,5,1,8,11,6,8],[10,1,4,6,2,5,1,4,4,4,5,1,13,4,4],[6,1,4,11,9,4,1,3,9,9,10,1,6,5,8]],"totalWinCoin":133000},"subGameInfo":{"subGamid":-1,"isMustJoin":-1},"coin":172974300,"spEffect":{"wincoin":0,"kind":0},"rtype":4,"resultCards":[6,1,4,11,9,4,1,3,9,9,10,1,6,5,8],"x":5,"y":3,"allFreeCnt":10,"lastBetCoin":172974300,"spLuXian":0,"nextBetLine":{"spcode":500},"pooljp":0,"freeResult":{"freeInfo":[]},"spcode":200},"uid":110917,"c":51,"code":200}
            let data = msg.data;
            if (data.rtype == 4) {
                cc.vv.gameData.OnRcvNetSpine(msg.data);

                if (this._gameInfo && this._gameInfo.bonusGame) {
                    if (this._gameInfo.bonusGame.scatterCnt > 0) {
                        this.showBottomInfo(true);
                    }
                }
            }
        }
    },

    restoreByServerData () {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo.bonusGame) {
            let bonusGame = deskInfo.bonusGame;
            //生成对应的Slots个数
            for (let i=1; i< bonusGame.currSlotIdx; i++) {
                //增加一个Slots
                let slotScript = this.add1Slot();

                slotScript.node.getComponent(cc.Widget).enabled = false;
                slotScript.node.y = this._slotsActiveList[0].node.y + slotScript.node.height*slotScript.node.scaleY*i;
            }
            //设置为当前活跃Slot
            this.setCurActiveSlot(bonusGame.currSlotIdx - 1); //默认是0

            //收集中奖池节点
            this._collect_jackpot.y = this.getCollectJackpotPos().y;

            //船变位置，变小
            // let targetScale = [0.86, 0.7, 0];
            // let posY = [282, 182, 250];
            //- this._spine_role.y =  this._slotsActiveList[this._slotsActiveList.length - 1].node.y + posY[this._slotsActiveList.length - 1];
            //- this._spine_role.scale = targetScale[this._slotsActiveList.length - 1];

            if (!cc.vv.gameData.isEnterMapGames()) { //优先地图游戏
                //开始移动Slots
                this.startMoveSlots();
                //清除数据，若数据存在，用来判断重启
                deskInfo.bonusGame = null;
            }

            if (this._gameInfo && this._gameInfo.bonusGame) {
                if (this._gameInfo.bonusGame.scatterCnt > 0) {
                    this.showBottomInfo(true);
                }
            }
        }
        else {
            //断线重连的显示
            // cc.vv.gameData.GetSlotsScript().ReconnectShow();
        }
    },

    setGameInfo (gameInfo) {
        this._gameInfo = gameInfo;
    },

    //开始移动
    OnStartMove () {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        let bonusGame =  this._gameInfo?this._gameInfo.bonusGame:deskInfo.bonusGame;
        if (bonusGame) {
            if (bonusGame.currSlotIdx + 1 === bonusGame.nextSlotIdx) {
                cc.vv.gameData.GetSlotsScript().SetStopTime(2.0);
                //需要向上移动Slots
                this.moveSlotUp();
            }
            else if (bonusGame.currSlotIdx === bonusGame.nextSlotIdx + 1) {
                cc.vv.gameData.GetSlotsScript().SetStopTime(2.0);
                //需要向下移动Slots
                this.moveSlotDown();
            }
            else {
                cc.vv.gameData.GetSlotsScript().SetStopTime(1.0);
            }
        }
    },

    //停止移动
    OnStopMove () {
        if (this._gameInfo && this._gameInfo.bonusGame) {
            //开始移动Slots
            this.startMoveSlots();

            //清除多余数据
            let deskInfo = cc.vv.gameData.getDeskInfo();
            deskInfo.bonusGame = null;
        }
    },

    startMoveSlots () {
        //设置新Slots为活跃Slots
        let bonusGame =  this._gameInfo?this._gameInfo.bonusGame:cc.vv.gameData.getDeskInfo().bonusGame;
        if (bonusGame.currSlotIdx + 1 === bonusGame.nextSlotIdx) { //Slots个数不够
            //生成新Slot
            this.add1Slot();
        }
        cc.vv.gameData.GetSlotsScript().stopSymboleWinEff();
        this.setCurActiveSlot(bonusGame.nextSlotIdx - 1);
        //开始移动Slots
        cc.vv.gameData.GetSlotsScript().StartMove();
        //请求数据
        this.scheduleOnce(()=>{
            this.reqBonusGame();
        }, 1.0);
    },

    /**
     * 请求子游戏数据51
     * @param rType 1选择子游戏 2转盘收集数 3子游戏选择  4多卷轴
     */
    reqBonusGame() {
        let req = {
            c:MsgId.SLOT_SUBGAME_DATA,
            gameid:cc.vv.gameData.getGameId(),
            data:{rtype:4}
        };
        cc.vv.NetManager.send(req, true);
    },

    //向上移动Slots
    moveSlotUp () {
        if (this._curSlotId <= 0) return;

        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.reel_up);

        let slotScript = this._slotsActiveList[this._curSlotId];

        //移动特效
        let spineSlotUp = slotScript.node.getChildByName("spineSlotUp");
        this.playSpine(spineSlotUp);

        //去掉对齐组件影响
        slotScript.node.getComponent(cc.Widget).enabled = false;
        //初始位置
        let startPos = this._slotsActiveList[this._curSlotId - 1].node.position;
        slotScript.node.position = startPos;
        //目标位置
        let interval = 0.8;
        let targetPosY = startPos.y + slotScript.node.height*slotScript.node.scaleY;
        cc.tween(slotScript.node).to(interval, {y:targetPosY}).call(()=>{
            spineSlotUp.active = false;
        }).start();

        //收集中奖池节点移动
        cc.tween(this._collect_jackpot).to(interval, {y:targetPosY + 180}).start();

        //船变位置，变小
        let targetScale = [0.86, 0.7, 0];
        let posY = [282, 182, 250];
        //- cc.tween(this._spine_role).to(interval, {y:targetPosY + posY[this._curSlotId], scale:targetScale[this._slotsActiveList.length - 1]}).start();
    },

    //向下移动Slots
    moveSlotDown () {
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.reel_down);

        //最上面的Slot
        let slotScript = this._slotsActiveList[this._slotsActiveList.length - 1];
        if (!slotScript) return;

        //移动特效(下面那个Slot播放)
        let downSlotScript = this._slotsActiveList[this._slotsActiveList.length - 2];
        if (!downSlotScript) return;

        let spineSlotDown = downSlotScript.node.getChildByName("spineSlotDown");
        this.playSpine(spineSlotDown);

        //初始位置
        // let curPos = slotScript.node.position;
        //目标位置
        let interval = 0.8;
        cc.tween(slotScript.node).to(interval, {y:downSlotScript.node.y}).call(()=>{
            spineSlotDown.active = false;
            //移除多出来的Slots
            this.delete1Slot();
        }).start();

        //收集中奖池节点移动
        cc.tween(this._collect_jackpot).to(interval, {y:downSlotScript.node.y + 180}).start();

        //船变位置，变大
        let targetScale = [0.86, 0.7, 0];
        let posY = [282, 182];
        //- cc.tween(this._spine_role).to(interval, {y:downSlotScript.node.y + posY[this._curSlotId], scale:targetScale[this._curSlotId]}).start();
    },

    //添加一个Slot
    add1Slot () {
        let slotScript = null;
        if (this._slotsCacheList.length>0) {
            slotScript = this._slotsCacheList.pop();
        }
        else {
            slotScript = this.createSlot();
        }
        slotScript.node.zIndex = 100 - this._slotsActiveList.length;
        slotScript.node.name = "slots" + this._slotsActiveList.length;
        slotScript.node.active = true;
        this._slotsActiveList.push(slotScript);

        return slotScript;
    },

    createSlot () {
        let slotNode = cc.instantiate(this._slotsTemplate);
        slotNode.active = true;
        slotNode.parent = this.node;

        //存到gamedata里面
        let cfg = cc.vv.gameData.getGameCfg();
        let slotScript = slotNode.getComponent(cfg.scripts.Slots);
        return slotScript;
    },

    //减少一个Slots
    delete1Slot () {
        let slotScript = this._slotsActiveList.pop();
        slotScript.node.active = false;
        this._slotsCacheList.push(slotScript);
    },

    //设置当前活跃Slots
    //SlotsId: 0,1,2
    setCurActiveSlot (slotId) {
        if (slotId >= this._slotsActiveList.length) return;

        this._curSlotId = slotId;

        //脚本不激活
        for (let slotScpt of this._slotsActiveList) slotScpt.enabled = false;

        //设置当前Slots
        let slotScript = this._slotsActiveList[this._curSlotId];
        slotScript.enabled = true;
        cc.vv.gameData.SetSlotsScript(slotScript);
    },

    //获取当前活跃Slots
    getCurActiveSlotScript () {
        return this._slotsActiveList[this._curSlotId];
    },

    //收集奖池位置
    getCollectJackpotPos () {
        let lastSlot = this._slotsActiveList[this._slotsActiveList.length - 1].node;
        return cc.v2(this._collect_jackpot.position.x, lastSlot.position.y + 180);
    },

    showBottomInfo (bShow) {
        if (bShow == this._bonusBottom.active) return;

        let resetCnt = 0;
        if (!this._bonusBottom.active && bShow) {
            resetCnt = 3;
        }

        this._bonusBottom.active = bShow;
        this._bonusBottom.y = this._slotsActiveList[0].node.y - 120;

       let spr_txt_scatter =  cc.find("spr_txt_scatter", this._bonusBottom);
        spr_txt_scatter.active = true;

        let spr_txt_freetimes =  cc.find("spr_txt_freetimes", this._bonusBottom);
        spr_txt_freetimes.active = false;

        if (this._gameInfo && this._gameInfo.bonusGame) {
            if (resetCnt == 0) resetCnt = 3 - (this._gameInfo.bonusGame.scatterCnt || 0);
            cc.find("spr_txt_scatter/lblScatterNum", this._bonusBottom).getComponent(cc.Label).string = resetCnt.toString();

            if (resetCnt <= 0) {
                spr_txt_scatter.active = false;
                spr_txt_freetimes.active = true;
            }
        }
    },

    setBottomInfoScatterCnt (scatterNum) {
        let resetCnt = 3 - scatterNum;
        // resetCnt = Math.max(resetCnt, 0);

        let spr_txt_scatter =  cc.find("spr_txt_scatter", this._bonusBottom);

        let lblScatterNum = cc.find("lblScatterNum", spr_txt_scatter);

        let spr_txt_freetimes =  cc.find("spr_txt_freetimes", this._bonusBottom);
        let lblFreeTimes =  cc.find("lblFreeTimes", spr_txt_freetimes);

        if (resetCnt > 0) {
            spr_txt_scatter.active = true;
            spr_txt_freetimes.active = false;

            this.scheduleOnce(()=>{
                lblScatterNum.getComponent(cc.Label).string = resetCnt.toString();
            }, 0.5);

            let spineBomb = cc.find("spineBomb", spr_txt_scatter);
            this.playSpine(spineBomb,"animation", false, ()=>{
                spineBomb.active = false;
            });
        }
        else if (resetCnt == 0) {
            spr_txt_scatter.active = true;
            spr_txt_freetimes.active = false;

            let spine_switch = cc.find("spine_switch", this._bonusBottom);
            this.playSpine(spine_switch,"animation", false, ()=>{
                spine_switch.active = false;
            });

            this.scheduleOnce(()=>{
                spr_txt_scatter.active = false;
                spr_txt_freetimes.active = true;
                lblFreeTimes.getComponent(cc.Label).string = "10";
            }, 0.5);
        }
        else if (resetCnt < 0) { //显示的是免费次数
            // lblFreeTimes
            spr_txt_scatter.active = false;
            spr_txt_freetimes.active = true;

            this.scheduleOnce(()=>{
                lblFreeTimes.getComponent(cc.Label).string = (10 + (-resetCnt*2)).toString();
            }, 0.5);

            let spineBomb = cc.find("spineBomb", spr_txt_freetimes);
            this.playSpine(spineBomb,"animation", false, ()=>{
                spineBomb.active = false;
            });
        }
    },

    getBottomRestScatterCnt () {
        let restCnt = parseInt(cc.find("spr_txt_scatter/lblScatterNum", this._bonusBottom).getComponent(cc.Label).string || 0);
        if (this._gameInfo.bonusGame.scatterCnt <= 3) {
          restCnt = 3 - this._gameInfo.bonusGame.scatterCnt;
          restCnt = Math.max(restCnt, 0);
        }
        return restCnt;
    },

    async collectScatter (globalPosArr) {
        if (globalPosArr.length <= 0) return;
        if (this.getBottomRestScatterCnt() <= 0) return; //最多3个

        this.showBottomInfo(true);

        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_collect);

        let scattterSymbol = cc.find("spr_scatter", this._bonusBottom);

        let endPos = cc.find("scatter_pos", this._bonusBottom).getPosition();
        let promiseArr = [];
        globalPosArr.forEach(v=>{
            let pos = this._bonusBottom.convertToNodeSpaceAR(v);
            let lz = cc.instantiate(scattterSymbol);
            lz.parent = this._bonusBottom;
            lz.x = pos.x;
            lz.y = pos.y;
            lz.active = true;

            promiseArr.push(new Promise((res)=>{
                lz.runAction(cc.sequence(cc.spawn(cc.moveTo(0.5, endPos).easing(cc.easeSineInOut()), cc.scaleTo(0.5, 0.3)), cc.callFunc(()=>{
                    res();
                }), cc.removeSelf()));
            }));
        });
        await Promise.all(promiseArr);

        //刷新数量
        this.setBottomInfoScatterCnt(this._gameInfo.bonusGame.scatterCnt);
    },

    //播放Spine
    playSpine (node, animationName="animation", isLoop=false, endCall=null) {
        return new Promise((success)=>{
            if (node) {
                node.active = true;
                console.log("播放节点[" + node.parent.name + "/" + node.name + "]的spine动作: " + animationName);
                node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
                if (!isLoop) {
                    node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                        if (endCall) endCall();
                        success(); //下一步
                    });
                }
                else {
                    success(); //下一步
                }
            }
            else {
                if (endCall) endCall();
                success(); //下一步
            }
        });
    },

    //播放Actions
    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    //等待时间
    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
