/**
 * 收集进度
 * @class goldTreasure_MapCollectProgress
 */
cc.Class({
    extends: cc.Component,

    properties: {
        percent:0,
        _isCollectState:false,

        lblCollectNum: cc.Label,

        progressBar: cc.ProgressBar,
        spine_renyu: sp.Skeleton,
        spine_tips: sp.Skeleton,
        collect_track_particle:cc.Node,

        spine_progress_complete: sp.Skeleton, //进度完成
        spine_progress_add: sp.Skeleton,  //进度增加
    },

    onLoad() {
        let progressData = cc.vv.gameData.progressData;

        this.setProgress(progressData.needCnt>0?progressData.totalCnt/progressData.needCnt:0);
        this.setCollectNum(progressData.needCnt - progressData.totalCnt);

        this._initListener();

        Global.GoddessOfDeathCollectProgress = this;
    },

    start() {
        this.showCollect(cc.vv.gameData.isOpenCollectProgress());
    },

    _initListener() {
        Global.btnClickEvent(cc.find("btnUnlock", this.node), this.onBtnUnlockClicked, this);
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)
    },

    onBtnUnlockClicked () {
        if (cc.vv.gameData.GetFreeTime() > 0) return;

        if (this.spine_tips.node.active && cc.vv.gameData.GetMaxBetIdx() >= cc.vv.gameData.needBet) {
          cc.vv.gameData.SetBetIdx(cc.vv.gameData.needBet);
          cc.vv.gameData.GetSlotsScript()._bottomScript.ShowBetCoin();
          //通知押注额修改
          Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, cc.vv.gameData.GetTotalBet());
        }
    },

    setCollectNum (num) {
        this.lblCollectNum.string = num.toString();
    },

    setBtnsClickEnable (enable) {
        cc.find("btnMapInfo", this.node).getComponent(cc.Button).interactable = enable;
        cc.find("btnUnlock", this.node).getComponent(cc.Button).interactable = enable;
    },

    onEventTotalbetUpdated (event) {
        this.showCollect(cc.vv.gameData.isOpenCollectProgress());
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param percent
     */
    async collectEnergy(globalPosArr, percent) {
        percent = Math.max(0, Math.min(1, percent));

        if (globalPosArr.length <= 0) return;

        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.m1_fly);

        let endPos = this.spine_renyu.node.getPosition();
        let promiseArr = [];
        globalPosArr.forEach(v=>{
            let pos = this.node.convertToNodeSpaceAR(v);
            let lz = cc.instantiate(this.collect_track_particle);
            lz.parent = this.node;
            lz.x = pos.x;
            lz.y = pos.y;
            lz.active = true;
            let p = lz.getComponent(cc.ParticleSystem);
            p.resetSystem();

            promiseArr.push(new Promise((res)=>{
                cc.tween(lz)
                    .to(0.5, {x:endPos.x, y:endPos.y},{easing:"easeInOut"})
                    .call(()=> {
                        lz.removeFromParent();
                        res();
                    })
                    .start();
            }));
        });
        await Promise.all(promiseArr);
        this.setProgress(percent);

        this.spine_renyu.node.active = true;
        this.spine_renyu.setAnimation(0, "animation", false);
        // cc.find("spine", this.spine_renyu.node).getComponent(sp.Skeleton).setAnimation(0, "animation", false);

        let progressData = cc.vv.gameData.progressData;
        let count = Math.max(0, progressData.needCnt - progressData.totalCnt);
        this.setCollectNum(count);
    },

    /**
     * 显示收集界面
     * @param boo
     */
    showCollect(boo) {
        if (this._isCollectState != boo) {
            if(boo) {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.unlock);

                this.spine_tips.node.active = true;
                this.spine_tips.setAnimation(0, "animation1", false);
                this.spine_tips.setCompleteListener(()=>{
                    this.spine_tips.node.active = false;
                    this.spine_tips.setCompleteListener(null);
                });
            }
            else {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.lock);

                this.spine_tips.node.active = true;
                this.spine_tips.setAnimation(0, "animation2", false);
                this.spine_tips.setCompleteListener(()=>{
                    this.spine_tips.setAnimation(0, "animation3", true);
                    this.spine_tips.setCompleteListener(null);
                });
            }
        }
        this._isCollectState = boo;
    },

    /**
     * 设置进度
     * @param percent
     */
    setProgress(percent) {
        if (percent > 0) {
            this.spine_progress_add.node.x = this.progressBar.node.width*percent;
            this.spine_progress_add.node.active = true;
            this.spine_progress_add.setAnimation(0, "animation", false);
            this.spine_progress_add.setCompleteListener(()=>{
                this.spine_progress_add.node.active = false;
                this.spine_progress_add.setCompleteListener(null);

                if (percent >= 1) {
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_full);

                    this.spine_progress_complete.node.active = true;
                    this.spine_progress_complete.setAnimation(0, "animation4", false);
                    this.spine_progress_complete.setCompleteListener(()=> {
                        this.spine_progress_complete.node.active = false;
                        this.spine_progress_complete.setCompleteListener(null);
                    });
                }
            });

            this.scheduleOnce(()=>{
                this.progressBar.progress = percent;
            }, 0.4);
        }
        else {
            this.progressBar.progress = 0;
        }
    },

    onBtnShowInfoClicked () {
        // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);
        Global.GoddessOfDeathMap.enterMap(true, true);
    },
});
