let WHEEL_COLOR_CFG = [
    [
        1,2,3,6,5,1,2,4,6,5
    ],
    [
        4,3,1,5,6,4,3,2,5,6
    ],
    [
        2,3,4,6,1,2,3,4,5,1
    ],
];


cc.Class({
    extends: require("GoddessOfDeath_subGameBase"),

    properties: {
        _subGameNodeName: "subGameMultWheel",

        _lblStartPrize: null,
        _lblPickMult: null,
        _sprPickTips: null,

        _wheelList: null,
        _grayMaskList: null,
        _spineWheelWin: null,

        _winMultList: null,
        _spineMultWinList: null,

        _btnSpin: null,
    },

    // LIFE-CYCLE CALLBACKS:

    async onLoad () {
        this._super();

        this._lblStartPrize = cc.find("nodePrizePool/theme163_game_c_2/lblStartPrize", this._node_main);
        this._lblPickMult = cc.find("nodePrizePool/theme163_game_c_3/lblPickMult", this._node_main);
        this._sprPickTips = cc.find("spinTips", this._node_main);

        let nodeWheel = cc.find("wheelNode", this._node_main);
        this._btnSpin = cc.find("btnSpin", nodeWheel);

        this._wheelList = [];
        this._grayMaskList = [];
        for (let i=1; i<=3; i++) {
            this._wheelList[i] = cc.find("rorationWheel" + i, nodeWheel);
            this._grayMaskList[i] = cc.find("grayMask" + i, nodeWheel);
        }

        this._spineWheelWin = cc.find("spineWheelWin", nodeWheel);

        this._winMultList = [];
        for (let i=1; i<=6; i++) {
            this._winMultList[i] = [];
            for (let j=1; j<=3; j++) {
                let winMultNode = cc.find("nodePrizePool/theme163_game6_2/win_" + i + "_" + j, this._node_main);
                if (winMultNode) this._winMultList[i][j] = winMultNode;
            }
        }

        this._spineMultWinList = [];
        for (let i=1; i<=6; i++) {
            let spineWin = cc.find("nodePrizePool/theme163_game6_2/spineWin" + i, this._node_main);
            spineWin.active = false;
            this._spineMultWinList[i] = spineWin;
        }

        //初始化各种显示
        this.init();
    },

    init () {
        this.setLabel(this._lblPickMult,"");
        this.setLabel(this._lblStartPrize, "");

        for (let wheel of this._wheelList) if (wheel) wheel.rotation = 0;
        for (let mask of this._grayMaskList) if (mask) mask.active = false;
        this._spineWheelWin.active = false;

        this._btnSpin.getComponent(cc.Button).interactable = true;

        this.resetWinResultPanel();

        for (let i=1; i<=6; i++) cc.find("nodePrizePool/theme163_game6_2/spineWin" + i, this._node_main).active = false;
    },

    restoreByData () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._subGameNode.active = true;

        //恢复已中奖颜色
        let curComb = gameInfo.finalColorComb[gameInfo.currStep - 1];
        for (let i=1; i<=curComb.length; i++) {
            this._wheelList[i].rotation = -36*this.getWheelColorPos(i,curComb[i-1]);
        }
        //已中奖倍数
        this.refreshCurWinResultPanel();
        //选择提示
        this.setPlayPickTipsAction(true);
    },

    //进入游戏
    async enterGame () {
        this.init();

        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        this.setLabel(this._lblStartPrize, Global.FormatNumToComma(gameInfo.startPrize));

        return new Promise(async (success)=>{
            if (gameInfo.currStep >0) {
                //断线重连
                //根据数据恢复显示
                this.restoreByData();
            }
            else {
                await this.showStart();
            }
            await this.showMain();
            await this.showResult();
            await this.exitGame();
            success();
        });
    },

    //退出游戏
    async exitGame () {
        return new Promise(async (success)=>{
            //全屏过渡
            await this.playFullScreen(2.0);
            this.setSubGameNodeVisible(false);
            success();
        });
    },

    //显示开始提示
    // async showStart () {
    //     return new Promise(async (success)=>{
    //         this._subGameNode.active = true;
    //         this._node_start.active = true;
    //         this._node_start.scale = 0;
    //         await this.playActions(this._node_start, [cc.scaleTo(0.35, 1.4), cc.scaleTo(0.15, 1.2)]);
    //         Global.btnClickEvent(this._node_start.getChildByName("btnStart"), ()=>{
    //             Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);
    //             this.playActions(this._node_start, [cc.scaleTo(0.15, 1.4), cc.scaleTo(0.35, 0)]);
    //             success();
    //         }, this);
    //     });
    // },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            //全屏过渡
            let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
            if (gameInfo.currStep <= 0) await this.playFullScreen(1.5);
            //初始化
            this._node_start.active = false;
            this._node_main.active = true;
            await this.awaitTime(0.2);
            //等待玩家选择操作
            await this.awaitOrOperate();
            //选择提示
            this.setPlayPickTipsAction(false);
            //等待
            await this.awaitTime(1.0);
            success();
        });
    },

    setPlayPickTipsAction (isPlay) {
        this._sprPickTips.stopAllActions();
        this._sprPickTips.scale = 1.0;
        if (isPlay) {
            this._sprPickTips.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.5,0.8), cc.scaleTo(0.2,1.0), cc.delayTime(1.0))));
            for (let mask of this._grayMaskList) if (mask) mask.active = false;
        }
    },

    async awaitOrOperate () {
        return new Promise(async (success, failed)=>{
            //提示规律跳动
            this.setPlayPickTipsAction(true);

            this._btnSpin.getComponent(cc.Button).interactable = true;
            this._btnSpin.off("click");
            Global.btnClickEvent(this._btnSpin, async ()=>{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);

                //停止操作提示动作
                this.setPlayPickTipsAction(false);
                this._btnSpin.getComponent(cc.Button).interactable = false;

                let resp = await cc.vv.gameData.reqSubGame(Global.GOLD_TREASURE_MAP_RTYPE.OPERATE_SUBGAME);
                if (resp.code === 200) {
                    let gameInfo = resp.data.mapInfo.gameInfo;
                    let curComb = gameInfo.finalColorComb[gameInfo.currStep - 1];

                    //转轮子1，2，3
                    await this.rotateWheelToTarget(curComb);
                    await this.awaitTime(7.5);
                    //飞点数特效，中倍数或加次数特效，mult飞特效
                    await this.flyWinColorToResultPanel(curComb);

                    if (gameInfo.mult <= 0) {
                        //提示规律跳动
                        this.setPlayPickTipsAction(true);
                        //设置可操作
                        this._btnSpin.getComponent(cc.Button).interactable = true;
                    }
                    else {
                        //播放中奖倍数
                        this.flyWinColorToMultPos(gameInfo.finalColorId);


                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.land4_full);
                        // 闪动3次
                        let animationList = ["animation", "animation2", "animation2", "animation3", "animation3", "animation3"];
                        this.playSpine(this._spineMultWinList[gameInfo.finalColorId], null,  animationList[gameInfo.finalColorId - 1], true);

                        success();
                    }
                }
                else {
                    console.log("返回数据错误!");
                    failed();
                }
            });
        });
    },

    async rotateWheelToTarget (curComb) {
        return new Promise(async success=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.land4_spin);
            for (let i=1; i<=3; i++) {
                let rorationWheel = this._wheelList[i];
                rorationWheel.angle = 0;

                let targetAngle = this.getWheelColorPos(i, curComb[i -1])*(-36);
                // targetAngle *= -1; //逆时针

                let diffAngle = targetAngle - rorationWheel.angle;
                let mRound = 6; //转动圈数

                //旋转
                await this.playActions(rorationWheel, [
                    cc.rotateTo(0.5*mRound, 360*mRound - diffAngle).easing(cc.easeSineInOut()),
                ]);

                //特效
                this._grayMaskList[i].active = true;
                this.playSpine(this._spineWheelWin, null, "animation" + i, false);
                await this.awaitTime(0.5);

                success();
            }
        });
    },

    resetWinResultPanel () {
        for (let i=1; i<=6; i++) {
            for (let j=1; j<=3; j++) {
                this._winMultList[i][j].color = cc.Color.GRAY;
            }
        }
    },

    //刷新当前中奖区
    refreshCurWinResultPanel () {
        this.resetWinResultPanel();

        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        //播放中奖倍数
            for (let i=0; i<gameInfo.currStep; i++) {
                let colorComb = gameInfo.finalColorComb[i];
                for (let colorIdx of colorComb) {
                    for (let j=1; j<=3; j++) {
                        if (this._winMultList[colorIdx][j].color.equals(cc.Color.GRAY)) {
                            this._winMultList[colorIdx][j].color = cc.Color.WHITE;
                            break;
                        }
                    }
                }
            }
    },

    //获取Wheel上对应颜色位置
    getWheelColorPos (wheelIdx, colorId) {
        let colorCfg = WHEEL_COLOR_CFG[wheelIdx - 1];
        for (let i=0; i<colorCfg.length; i++) {
            if (colorCfg[i] == colorId) {
                return i;
            }
        }
    },

    //获取到中奖颜色
    getColorWinNode (colorId) {
        for (let i=1; i<=3; i++) {
            let colorNode = this._winMultList[colorId][i];
            if (colorNode.color.equals(cc.Color.GRAY)) {
                return colorNode;
            }
        }
    },

    getColorCenterNode (colorId) {
        return this._winMultList[colorId][2];//返回中间位置，就是当前颜色的重心
    },

    //飞中奖颜色到结果特效
    async flyWinColorToResultPanel (curComb) {
        return new Promise(async (success)=> {
            // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.zhuanpan_show);
            for (let i=1; i<=3; i++) {
                //飞动作
                let startNode = cc.find("wheelNode/wheelWinFrame/node" + i, this._node_main);
                let targetNode = this.getColorWinNode(curComb[i - 1]);
                await this.playFlyEffect(startNode, targetNode, curComb[i - 1]);
                //点亮颜色
                if (targetNode) targetNode.color = cc.Color.WHITE;
            }
            //下一步
            success();
        });
    },

    async flyWinColorToMultPos (winColor) {
        //飞倍数到奖池
        let startNode = this.getColorCenterNode(winColor);
        let targetNode = cc.find("nodePrizePool/theme163_game_c_3", this._node_main);
        await this.playFlyEffect(startNode, targetNode);

        //奖池中奖特效
        let nodeFly = cc.find("nodePrizePool/spineNodeMult", this._node_main);
        this.playSpine(nodeFly);
        await this.awaitTime(0.2);
        let mult = cc.vv.gameData.mapInfo.gameInfo.mult;
        this.setLabel(this._lblPickMult, mult? mult + "X":"");
    },

    //飞特效
    async playFlyEffect (startNode, targetNode, winColorId) {
        return new Promise(async (success)=> {
            if (startNode && targetNode) {
                let startPos = this._node_main.convertToNodeSpaceAR(startNode.parent.convertToWorldSpaceAR(startNode.position));
                let targetPos = this._node_main.convertToNodeSpaceAR(targetNode.parent.convertToWorldSpaceAR(targetNode.position));
                let nodeFly = cc.find("nodeFlyMultNum", this._node_main);
                nodeFly.position = startPos;
                nodeFly.scale = 1.0;

                nodeFly.getComponent(cc.ParticleSystem).resetSystem();

                if (winColorId) {
                    let animationList = ["animation", "animation2", "animation2", "animation3", "animation3", "animation3"];
                    let dianliang = nodeFly.getChildByName("shoujidianliang");
                    this.playSpine(dianliang, ()=>{
                        dianliang.active = false;
                    }, animationList[1], false);
                }

                await this.playActions(nodeFly, [cc.moveTo(0.5, targetPos), cc.scaleTo(0.1, 0)]);
            }
            //下一步
            success();
        });
    },

    //显示游戏结果
    async showResult () {
        return new Promise(async (success)=>{
            this._node_win.active = true;

            let ui = this._node_win.getChildByName("ui");
            ui.scale = 0;

            let baseCoin = Global.FormatCommaNumToNum(this._lblStartPrize.getComponent(cc.Label).string);
            let mult = cc.vv.gameData.mapInfo.gameInfo.mult;

            //屏蔽collect按钮
            let btnCollect = ui.getChildByName("btnCollect");
            btnCollect.getComponent(cc.Button).enabled = false;

            //显示公式
            this.setLabel(ui.getChildByName("lblWinCoinShow"), mult + " X " + this.convertNumToShortStr(baseCoin) + " = " + this.convertNumToShortStr(mult*baseCoin));
            //动态刷新赢取金币数
            this.rollToNumOfLabel(ui.getChildByName("lblWinCoin"), mult*baseCoin);
            cc.vv.gameData.setSubGameWinCoin(mult*baseCoin);

            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.popup_map2);
            //播放动画
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            //开启collect按钮
            btnCollect.getComponent(cc.Button).enabled = true;
            let self = this;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);

                btnCollect.getComponent(cc.Button).enabled = false;
                ui.getChildByName("lblWinCoin").stopAllActions();
                self.setLabel(ui.getChildByName("lblWinCoin"), self.convertNumToShortStr(mult*baseCoin));
                self.playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);
                success();
            };
            cc.vv.gameData.checkAutoPlay(btnCollect, clickFunc);
            Global.btnClickEvent(btnCollect, ()=>{
                btnCollect.stopAllActions();
                clickFunc();
            }, this);
        });
    },
});
