/*
* 子游戏基类
 */

cc.Class({
    extends: cc.Component,

    properties: {
        _soundPath: "games/GoddessOfDeath/",

        _subGameNodeName: "subGame____", //需要被重新赋值
        _subGameNode: null,

        _spineNodeLoading: null,

        _node_start: null,
        _node_main: null,
        _node_win: null,

        machine: {
            default : null,
            visible : false
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._subGameNode = cc.find(this._subGameNodeName, this.node);
        this._spineNodeLoading = cc.find("spineNodeLoading", this._subGameNode);

        this._node_start = cc.find("node_start", this._subGameNode);
        this._node_main = cc.find("node_main", this._subGameNode);
        this._node_win = cc.find("node_win", this._subGameNode);

        this._subGameNode.active = false;
        this._spineNodeLoading.active = false;

        this._node_start.active = false;
        this._node_main.active = false;
        this._node_win.active = false;
    },

    //进入游戏
    async enterGame (data) {
       // Todo ... 需要重写
    },

    //退出游戏
    async exitGame () {
        // Todo ... 需要重写
    },

    // //显示开始提示
    // async showStart () {
    //     // Todo ... 需要重写
    // },

    //显示开始提示
    async showStart () {
        return new Promise(async (success)=>{
            this._subGameNode.active = true;
            this._node_start.active = true;

            let ui = cc.find("ui", this._node_start);
            ui.scale = 0;

            let btnStart = ui.getChildByName("btnStart");
            btnStart.getComponent(cc.Button).enabled = false;

            await this.playActions(ui, [cc.scaleTo(0.35, 1.4), cc.scaleTo(0.15, 1.2)]);
            btnStart.getComponent(cc.Button).enabled = true;

            let self = this;
            let clickFunc = async ()=>{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);
                btnStart.getComponent(cc.Button).enabled = false;

                await self.playActions(ui, [cc.scaleTo(0.15, 1.4), cc.scaleTo(0.35, 0)]);
                self._node_start.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btnStart, clickFunc);
            Global.btnClickEvent(btnStart, async ()=>{
                btnStart.stopAllActions();
                clickFunc()
            }, this);
        });
    },

    //显示游戏主体
    async showMain () {
        // Todo ... 需要重写
    },

    //显示游戏结果
    async showResult () {
        // Todo ... 需要重写
    },

    async playFullScreen (awaitTime) {
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.indicate);

        //全屏过渡
        this.setFullScreenVisible(true);
        this.playSpine(this._spineNodeLoading,null,"skill");
        await this.awaitTime(awaitTime || 1.0);
        this.setFullScreenVisible(false);
    },

    setFullScreenVisible (visible) {
        this._spineNodeLoading.active = visible;
    },

    setSubGameNodeVisible (visible) {
        this._subGameNode.active = visible;

        if (!visible) {
            this._node_start.active = false;
            this._node_main.active = false;
            this._node_win.active = false;
        }
    },

    //转化成KMB等数据
    convertNumToShortStr (num) {
        return Global.convertNumToShort(num, 1000, 1, ['', 'K', 'M', 'B', 'T', 'Q']);
    },

    //滚动Label数字
    rollToNumOfLabel (label, num) {
        Global.doRoallNumEff(label, 0, num, 2,null,null,0,true);
    },

    //设置Label显示
    setLabel (node, str) {
        if (node) node.getComponent(cc.Label).string = str;
    },

    //播放Spine
    playSpine (node, endCall, animationName="animation", isLoop=false) {
        if (node) {
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
            if (!isLoop) {
                node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    if (endCall) endCall();
                });
            }
        }
        else {
            if (endCall) endCall();
        }
    },

    //播放Actions
    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    //等待时间
    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
