/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        mapInfo   : null,   // 收集游戏相关信息
        progressData  : null,   // 能量数据

        _subGameWinCoin:0,  //地图游戏赢钱
        needBet   : 0,      //需要押注
    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){

        // let msg43 = {"c":43,"deskinfo":{"curround":1,"restFreeCount":10,"gameid":464,"deskid":"647519","line":20,"basecoin":1,"singleBet":9,"addMult":1,"uuid":"6475191605000080","mults":[10000,20000,30000,40000,50000,60000,70000,80000,90000],"user":{"uid":103617,"coin":10321916736,"sex":1,"level":9,"usericon":"","svip":0,"playername":"Guest103617"},"totalBet":90000,"state":2,"freeResult":{"freeInfo":{"addMult":1,"freeCnt":10},"triFreeCnt":1},"subGame":{"isMustJoin":-1,"subGameId":-1},"mapInfo":{"totalCnt":4,"progressData":{"totalCnt":44,"needCnt":75,"totalCoin":3960000},"needBet":2,"freeInfo":[],"state":0,"restStep":1,"nextGame":4,"completeGame":[1,5,4,3],"totalCoin":350000,"prevGame":3,"gameInfo":[]},"allFreeCount":10,"freeWinCoin":0,"currmult":9,"resultCards":[]},"gameid":464,"code":200,"gameJackpot":{"jp":[11,46,541,4657],"unlock":[40000,60000,90000,500000],"id":464}}
        // deskInfo = msg43.deskinfo;

       this._super(deskInfo,gameId,gameJackpot);

        this.mapInfo = this._deskInfo.mapInfo;
        this.progressData = this.mapInfo.progressData;
        this.needBet = this.mapInfo.needBet;
    },

    //本轮旋转赢钱
    GetGameWin:function(){
        let winCoin =  this._gameInfo.wincoin
        if (this._gameInfo.mapFreeGameData && this._gameInfo.mapFreeGameData.length > 0) {
            winCoin = 0;
            for (let d of this._gameInfo.mapFreeGameData) {
                winCoin += d.winCoin;
            }
        }
        return winCoin;
    },

    GetMaxBetIdx() {
      return this._deskInfo.mults.length;
    },

    SetSubGameData:function(data){
        this._subGame = data
    },

    GetSubGameData:function(){
        return this._subGame
    },

    getSubGameWinCoin(){
        return this._subGameWinCoin;
    },
    setSubGameWinCoin(val){
        this._subGameWinCoin = val;
    },

    //是否进入地图
    isEnterMapGames:function(){
        return cc.vv.gameData.mapInfo.state != Global.GOLD_TREASURE_MAP_STATE.COLLECT_ENERGY;
    },

    //是否触发免费游戏
    isTriggerFreeGames: function () {
        return this._deskInfo.restFreeCount > 0 && this._deskInfo.restFreeCount == this._deskInfo.allFreeCount;
    },

    //是否免费游戏结束
    isFinishFreeGames: function () {
        return this._deskInfo.restFreeCount == 0 && this._deskInfo.allFreeCount > 0;
    },

    //是否在免费游戏中
    isFreeGamesTime: function () {
        return this._deskInfo.restFreeCount > 0 && this._deskInfo.restFreeCount < this._deskInfo.allFreeCount;
    },

    isMultipleSlots: function () {
        return this._gameInfo && this._gameInfo.bonusGame;
    },

    isOpenCollectProgress: function () {
        return this.GetBetIdx() >= this.needBet;
    },

    //转一次
    ReqSpin:function(curBetIdx){
        let req = {c: MsgId.SLOT_START};
        req.betIndex = curBetIdx;
        req.gameid = this._gameId;  //添加
        cc.vv.NetManager.send(req,true);
    },

    OnRcvNetSpine:function(msg){
        if(msg.code == 200){
            // msg = {"allFreeCnt":0,"c":44,"resultCards":[12,12,12,12,2,6,11,13,2,6,6,5,11,12,6],"betcoin":1500000,"wincoin":1125000,"zjLuXian":[{"mult":1,"coin":750000,"indexs":[1,2,3],"xlid":2,"card":5}],"freeResult":{"freeInfo":[],"triFreeCnt":0},"subGameInfo":{"isMustJoin":-1,"subGamid":-1},"mults":[10000,20000,50000,100000,150000,200000,300000,400000,500000,600000,700000,800000,900000,1000000,1500000,2000000,2500000,3000000,3500000,4000000,4500000,5000000,6000000,7000000,8000000],"jackpot":{"coinIdxs":[8,14,1]},"coin":11799337390,"pooljp":0,"nextBetLine":{"spcode":500},"spcode":200,"addMult":1,"spLuXian":0,"freeCnt":0,"spEffect":{"wincoin":1125000,"kind":0},"code":200,"mapInfo":{"nextGame":5,"totalCoin":1517812,"prevGame":0,"freeInfo":[],"state":0,"gameInfo":[],"restStep":1,"totalCnt":4,"progressData":{"needCnt":65,"curCoin":0,"totalCoin":10500000,"totalCnt":7},"completeGame":[]},"lastBetCoin":11798212390,"freeWinCoin":0,"debugfree":{"threshold":80,"random_threshold":33,"bonusControl":200,"random_sub":324,"freerate":20},"scatterZJLuXian":{"mult":0,"coin":0,"indexs":[]}};

            if (msg.spcode && msg.spcode==967) {
                cc.vv.FloatTip.show("流程错误！！！");
                return;
            }

            if (msg.bonusGame) {
                if (!msg.bonusGame.currResultCards) {
                    msg.bonusGame.currResultCards = msg.resultCards;
                }

                if (!msg.freeResult) {
                    msg.bonusGame.freeResult = msg.freeResult;
                }
            }

            this._deskInfo.user.coin = msg.coin;
            this._gameInfo = msg;

            //最好是让浩然在bonus游戏51协议中加入两字段数据
            if (msg.freeCnt || msg.freeCnt == 0) this._deskInfo.restFreeCount = msg.freeCnt;
            if (msg.allFreeCnt || msg.allFreeCnt == 0) this._deskInfo.allFreeCount = msg.allFreeCnt;

            this.GetSlotsScript().onMsgSpine(msg)

            if (msg.mapInfo) {
                this.mapInfo = msg.mapInfo; //更新mapInfo
                this.progressData = msg.mapInfo.progressData;
            }
        }
    },

    /**
     * 请求子游戏数据51
     * @param rType 1选择子游戏 2转盘收集数 3子游戏选择
     */
    reqSubGame(rType, choiceId) {
        return new Promise(res=>{
            let req = {
                c:MsgId.SLOT_SUBGAME_DATA,
                gameid:this._gameId,
                data:{rtype:rType}
            };
            if (rType == 1) req.data.choiceGameId = choiceId;
            if (rType == 3) req.data.choiceId = choiceId;

            let resp = (msg)=>{
                cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, resp, false, this);

                if (msg.code === 200) { //更新mapInfo
                    if (msg.data.mapInfo) this.mapInfo = msg.data.mapInfo;
                }
                res(msg);
            }
            cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, resp, this);
            cc.vv.NetManager.send(req, true);
        });
    },

});
